/**
 * Build the bundled knowledge base from a local checkout of transformers.js.
 *
 * Usage:
 *   TRANSFORMERS_JS_DOCS=/path/to/transformers.js/packages/transformers/docs \
 *     node scripts/build-knowledge.mjs
 *
 * The generated file is committed so the demo can run without a docs checkout.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

const docsRoot = process.env.TRANSFORMERS_JS_DOCS
  ? resolve(process.env.TRANSFORMERS_JS_DOCS)
  : resolve(root, "../../packages/transformers/docs");

const sourceRoot = join(docsRoot, "source");
const snippetRoot = join(docsRoot, "snippets");

const DOC_FILES = [
  "index.md",
  "installation.md",
  "pipelines.md",
  "custom_usage.md",
  "guides/dtypes.md",
  "guides/private.md",
  "guides/webgpu.md",
  "guides/node-audio-processing.md",
  "integrations/vercel-ai-sdk.md",
  "tutorials/next-ai-sdk.md",
  "tutorials/next.md",
  "tutorials/node.md",
  "tutorials/react.md",
  "tutorials/vanilla-js.md",
];

const INCLUDE_RE =
  /<include>\s*\{[\s\S]*?"path"\s*:\s*"([^"]+)"[\s\S]*?\}\s*<\/include>/g;

function resolveIncludes(text, seen = new Set()) {
  return text.replace(INCLUDE_RE, (_, includePath) => {
    const absolute = resolve(sourceRoot, includePath);
    if (seen.has(absolute)) return "";
    seen.add(absolute);

    let snippet;
    try {
      snippet = readFileSync(absolute, "utf8");
    } catch {
      return `\n> Documentation snippet not bundled: ${includePath}\n`;
    }

    // The supported-model list is ~88 KB and would dominate the index.
    if (absolute.endsWith("5_supported-models.snippet")) {
      return [
        "",
        "> The full, up-to-date list of supported models is maintained at",
        "> https://huggingface.co/docs/transformers.js/index#supported-models.",
        "",
      ].join("\n");
    }

    return resolveIncludes(snippet, seen);
  });
}

function getTitle(markdown, fallback) {
  const match = markdown.match(/^#\s+(.+)$/m);
  return match ? match[1].replace(/`/g, "").trim() : fallback;
}

function normalize(markdown) {
  return markdown
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

const docs = [];
for (const file of DOC_FILES) {
  const absolute = join(sourceRoot, file);
  let raw;
  try {
    raw = readFileSync(absolute, "utf8");
  } catch (error) {
    console.warn(`Skipping ${file}: ${error.message}`);
    continue;
  }

  const content = normalize(resolveIncludes(raw));
  if (!content) continue;

  const id = file.replace(/\.md$/, "");
  docs.push({
    id,
    title: getTitle(content, id),
    source: `https://github.com/huggingface/transformers.js/blob/main/packages/transformers/docs/source/${file}`,
    content,
  });
}

if (docs.length === 0) {
  throw new Error(`No documentation found under ${sourceRoot}`);
}

const output = `// Generated by scripts/build-knowledge.mjs. Do not edit by hand.
// Source: https://github.com/huggingface/transformers.js (Apache-2.0)

export const DOCS = ${JSON.stringify(docs, null, 2)};
`;

const outFile = join(root, "src/knowledge/docs.js");
mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, output);

const bytes = docs.reduce((sum, doc) => sum + doc.content.length, 0);
console.log(
  `Wrote ${docs.length} documents (${(bytes / 1024).toFixed(1)} KiB) to ${relative(root, outFile)}`,
);
for (const doc of docs) {
  console.log(`  ${doc.id.padEnd(36)} ${(doc.content.length / 1024).toFixed(1)} KiB`);
}
